actions.script:
const given = name => (typeof ec.context[name] === 'undefined' ? null : ec.context[name])
let out = {}
let error = ''
ec.message.pushErrors()
try {
    out = ec.service.sync().name('mantle.humanres.AttendanceServices.record#KioskPunch')
        .parameters({badgeText: given('badgeText'), pin: given('pin'), directionEnumId: given('directionEnumId'),
            operationKey: given('operationKey')})
        .disableAuthz().requireNewTransaction(true).call() || {}
    if (ec.message.hasError()) error = ec.message.getErrorsString()
} catch (e) {
    error = String(e.message || e)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
ec.web.sendJsonResponse({out, error, userId: ec.user.userId || null})
